CREATE TABLE IF NOT EXISTS statarena_app.catalog_records (
 resource_id bigint NOT NULL REFERENCES statarena_app.catalog_editions(resource_id) ON DELETE CASCADE,
 record_kind text NOT NULL, path integer[] NOT NULL,
 parent_kind text, parent_path integer[], position integer, metric_label text,
 missing text[] NOT NULL, null_groups text[] NOT NULL, negative_zero text[] NOT NULL DEFAULT '{}', attributes jsonb NOT NULL,
 PRIMARY KEY(resource_id,record_kind,path),
 FOREIGN KEY(resource_id,parent_kind,parent_path)
   REFERENCES statarena_app.catalog_records(resource_id,record_kind,path) ON DELETE CASCADE,
 UNIQUE NULLS NOT DISTINCT(resource_id,record_kind,parent_path,position),
 CHECK(coalesce(array_ndims(path)=1,true) AND array_position(path,NULL) IS NULL AND 0<=ALL(path)),
 CHECK(parent_path IS NULL OR (coalesce(array_ndims(parent_path)=1,true) AND array_position(parent_path,NULL) IS NULL AND 0<=ALL(parent_path))),
 CHECK(array_position(missing,NULL) IS NULL AND array_position(null_groups,NULL) IS NULL AND array_position(negative_zero,NULL) IS NULL),
 CHECK(octet_length(attributes::text)<=8388608),
 CHECK(statarena_app.catalog_attributes_valid(record_kind,attributes)),
 CHECK(coalesce(CASE record_kind
 WHEN 'cat_archive_goals' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_archive_goals_competitions' THEN (parent_kind='cat_archive_goals' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_goals_competitions_events' THEN (parent_kind='cat_archive_goals_competitions' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_goals_index' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_archive_goals_index_seasons' THEN (parent_kind='cat_archive_goals_index' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_results' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_archive_results_competitions' THEN (parent_kind='cat_archive_results' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_results_competitions_matches' THEN (parent_kind='cat_archive_results_competitions' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_results_source_additional_sources' THEN (parent_kind='cat_archive_results' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_results_index' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_archive_results_index_seasons' THEN (parent_kind='cat_archive_results_index' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_archive_results_index_source_additional_sources' THEN (parent_kind='cat_archive_results_index' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_club_links' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_club_links_ambiguous' THEN (parent_kind='cat_club_links' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_club_links_links' THEN (parent_kind='cat_club_links' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NOT NULL)
 WHEN 'cat_club_links_unmatched' THEN (parent_kind='cat_club_links' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'cat_cup_nations_results' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'cat_cup_nations_results_matches' THEN (parent_kind='cat_cup_nations_results' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
