CREATE OR REPLACE FUNCTION statarena_app.support_attributes_valid(kind text,a jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(CASE kind
WHEN 'support_standing' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['competition','season','source','fetched_at']::text[])='{}'::jsonb AND (a ? 'competition' AND (a->'competition'='null'::jsonb OR (jsonb_typeof(a->'competition')='string'))) AND (a ? 'season' AND (a->'season'='null'::jsonb OR (jsonb_typeof(a->'season')='string'))) AND (a ? 'source' AND (a->'source'='null'::jsonb OR (jsonb_typeof(a->'source')='string'))) AND (a ? 'fetched_at' AND (a->'fetched_at'='null'::jsonb OR (jsonb_typeof(a->'fetched_at')='string'))))
WHEN 'support_standing_table' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['name']::text[])='{}'::jsonb AND (a ? 'name' AND (a->'name'='null'::jsonb OR (jsonb_typeof(a->'name')='string'))))
WHEN 'support_standing_row' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['team_id','uefa_id','image_url','name','wins','draws','losses','played','points','goals_for','goals_against','difference','position']::text[])='{}'::jsonb AND (a ? 'team_id' AND (a->'team_id'='null'::jsonb OR (jsonb_typeof(a->'team_id')='string'))) AND (a ? 'uefa_id' AND (a->'uefa_id'='null'::jsonb OR (jsonb_typeof(a->'uefa_id')='string'))) AND (a ? 'image_url' AND (a->'image_url'='null'::jsonb OR (jsonb_typeof(a->'image_url')='string'))) AND (a ? 'name' AND (a->'name'='null'::jsonb OR (jsonb_typeof(a->'name')='string'))) AND (a ? 'wins' AND (a->'wins'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'wins')='number' THEN (a->>'wins')::integer IS NOT NULL ELSE false END))) AND (a ? 'draws' AND (a->'draws'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'draws')='number' THEN (a->>'draws')::integer IS NOT NULL ELSE false END))) AND (a ? 'losses' AND (a->'losses'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'losses')='number' THEN (a->>'losses')::integer IS NOT NULL ELSE false END))) AND (a ? 'played' AND (a->'played'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'played')='number' THEN (a->>'played')::integer IS NOT NULL ELSE false END))) AND (a ? 'points' AND (a->'points'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'points')='number' THEN (a->>'points')::integer IS NOT NULL ELSE false END))) AND (a ? 'goals_for' AND (a->'goals_for'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'goals_for')='number' THEN (a->>'goals_for')::integer IS NOT NULL ELSE false END))) AND (a ? 'goals_against' AND (a->'goals_against'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'goals_against')='number' THEN (a->>'goals_against')::integer IS NOT NULL ELSE false END))) AND (a ? 'difference' AND (a->'difference'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'difference')='number' THEN (a->>'difference')::integer IS NOT NULL ELSE false END))) AND (a ? 'position' AND (a->'position'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'position')='number' THEN (a->>'position')::integer IS NOT NULL ELSE false END))))
WHEN 'support_stadium' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['stadium_id','capacity','capacity_as_of','coordinates_lat','coordinates_lon','created','opened','fetched_at','source_url']::text[])='{}'::jsonb AND (a ? 'stadium_id' AND (a->'stadium_id'='null'::jsonb OR (jsonb_typeof(a->'stadium_id')='string'))) AND (a ? 'capacity' AND (a->'capacity'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'capacity')='number' THEN (a->>'capacity')::integer IS NOT NULL ELSE false END))) AND (a ? 'capacity_as_of' AND (a->'capacity_as_of'='null'::jsonb OR (jsonb_typeof(a->'capacity_as_of')='string'))) AND (a ? 'coordinates_lat' AND (a->'coordinates_lat'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'coordinates_lat')='number' THEN (a->>'coordinates_lat')::double precision IS NOT NULL ELSE false END))) AND (a ? 'coordinates_lon' AND (a->'coordinates_lon'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'coordinates_lon')='number' THEN (a->>'coordinates_lon')::double precision IS NOT NULL ELSE false END))) AND (a ? 'created' AND (a->'created'='null'::jsonb OR (jsonb_typeof(a->'created')='string'))) AND (a ? 'opened' AND (a->'opened'='null'::jsonb OR (jsonb_typeof(a->'opened')='string'))) AND (a ? 'fetched_at' AND (a->'fetched_at'='null'::jsonb OR (jsonb_typeof(a->'fetched_at')='string'))) AND (a ? 'source_url' AND (a->'source_url'='null'::jsonb OR (jsonb_typeof(a->'source_url')='string'))))
WHEN 'support_stadium_plan' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['title','url','image_url','source','detail','format','allow_geolocation','embedded']::text[])='{}'::jsonb AND (a ? 'title' AND (a->'title'='null'::jsonb OR (jsonb_typeof(a->'title')='string'))) AND (a ? 'url' AND (a->'url'='null'::jsonb OR (jsonb_typeof(a->'url')='string'))) AND (a ? 'image_url' AND (a->'image_url'='null'::jsonb OR (jsonb_typeof(a->'image_url')='string'))) AND (a ? 'source' AND (a->'source'='null'::jsonb OR (jsonb_typeof(a->'source')='string'))) AND (a ? 'detail' AND (a->'detail'='null'::jsonb OR (jsonb_typeof(a->'detail')='string'))) AND (a ? 'format' AND (a->'format'='null'::jsonb OR (jsonb_typeof(a->'format')='string'))) AND (a ? 'allow_geolocation' AND (a->'allow_geolocation'='null'::jsonb OR (jsonb_typeof(a->'allow_geolocation')='boolean'))) AND (a ? 'embedded' AND (a->'embedded'='null'::jsonb OR (jsonb_typeof(a->'embedded')='boolean'))))
WHEN 'support_club' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['coach_name','coach_photo_url','coach_photo_author','coach_photo_license','coach_photo_source_url','founded','stadium','stadium_alias','stadium_id','fetched_at','source_url']::text[])='{}'::jsonb AND (a ? 'coach_name' AND (a->'coach_name'='null'::jsonb OR (jsonb_typeof(a->'coach_name')='string'))) AND (a ? 'coach_photo_url' AND (a->'coach_photo_url'='null'::jsonb OR (jsonb_typeof(a->'coach_photo_url')='string'))) AND (a ? 'coach_photo_author' AND (a->'coach_photo_author'='null'::jsonb OR (jsonb_typeof(a->'coach_photo_author')='string'))) AND (a ? 'coach_photo_license' AND (a->'coach_photo_license'='null'::jsonb OR (jsonb_typeof(a->'coach_photo_license')='string'))) AND (a ? 'coach_photo_source_url' AND (a->'coach_photo_source_url'='null'::jsonb OR (jsonb_typeof(a->'coach_photo_source_url')='string'))) AND (a ? 'founded' AND (a->'founded'='null'::jsonb OR (jsonb_typeof(a->'founded')='string'))) AND (a ? 'stadium' AND (a->'stadium'='null'::jsonb OR (jsonb_typeof(a->'stadium')='string'))) AND (a ? 'stadium_alias' AND (a->'stadium_alias'='null'::jsonb OR (jsonb_typeof(a->'stadium_alias')='string'))) AND (a ? 'stadium_id' AND (a->'stadium_id'='null'::jsonb OR (jsonb_typeof(a->'stadium_id')='string'))) AND (a ? 'fetched_at' AND (a->'fetched_at'='null'::jsonb OR (jsonb_typeof(a->'fetched_at')='string'))) AND (a ? 'source_url' AND (a->'source_url'='null'::jsonb OR (jsonb_typeof(a->'source_url')='string'))))
