WHEN 'support_nations_fixture' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['fixture_date','fixture_key','home','away','home_id','away_id','league','status','group_number','round','score']::text[])='{}'::jsonb AND (a ? 'fixture_date' AND (a->'fixture_date'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'fixture_date')='string' AND (a->>'fixture_date') ~ '^\d{4}-\d{2}-\d{2}$' THEN (a->>'fixture_date')::date IS NOT NULL ELSE false END))) AND (a ? 'fixture_key' AND (a->'fixture_key'='null'::jsonb OR (jsonb_typeof(a->'fixture_key')='string'))) AND (a ? 'home' AND (a->'home'='null'::jsonb OR (jsonb_typeof(a->'home')='string'))) AND (a ? 'away' AND (a->'away'='null'::jsonb OR (jsonb_typeof(a->'away')='string'))) AND (a ? 'home_id' AND (a->'home_id'='null'::jsonb OR (jsonb_typeof(a->'home_id')='string'))) AND (a ? 'away_id' AND (a->'away_id'='null'::jsonb OR (jsonb_typeof(a->'away_id')='string'))) AND (a ? 'league' AND (a->'league'='null'::jsonb OR (jsonb_typeof(a->'league')='string'))) AND (a ? 'status' AND (a->'status'='null'::jsonb OR (jsonb_typeof(a->'status')='string'))) AND (a ? 'group_number' AND (a->'group_number'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'group_number')='number' THEN (a->>'group_number')::integer IS NOT NULL ELSE false END))) AND (a ? 'round' AND (a->'round'='null'::jsonb OR (jsonb_typeof(a->'round')='string'))) AND (a ? 'score' AND (a->'score'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'score')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'score'))=a->'score' ELSE false END))))
WHEN 'support_cup' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['name','season','source_license','source_name','source_url']::text[])='{}'::jsonb AND (a ? 'name' AND (a->'name'='null'::jsonb OR (jsonb_typeof(a->'name')='string'))) AND (a ? 'season' AND (a->'season'='null'::jsonb OR (jsonb_typeof(a->'season')='string'))) AND (a ? 'source_license' AND (a->'source_license'='null'::jsonb OR (jsonb_typeof(a->'source_license')='string'))) AND (a ? 'source_name' AND (a->'source_name'='null'::jsonb OR (jsonb_typeof(a->'source_name')='string'))) AND (a ? 'source_url' AND (a->'source_url'='null'::jsonb OR (jsonb_typeof(a->'source_url')='string'))))
WHEN 'support_cup_fixture' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['fixture_date','group_name','num','round','team1','team2','score','full_time','half_time','extra_time','penalties']::text[])='{}'::jsonb AND (a ? 'fixture_date' AND (a->'fixture_date'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'fixture_date')='string' AND (a->>'fixture_date') ~ '^\d{4}-\d{2}-\d{2}$' THEN (a->>'fixture_date')::date IS NOT NULL ELSE false END))) AND (a ? 'group_name' AND (a->'group_name'='null'::jsonb OR (jsonb_typeof(a->'group_name')='string'))) AND (a ? 'num' AND (a->'num'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'num')='number' THEN (a->>'num')::integer IS NOT NULL ELSE false END))) AND (a ? 'round' AND (a->'round'='null'::jsonb OR (jsonb_typeof(a->'round')='string'))) AND (a ? 'team1' AND (a->'team1'='null'::jsonb OR (jsonb_typeof(a->'team1')='string'))) AND (a ? 'team2' AND (a->'team2'='null'::jsonb OR (jsonb_typeof(a->'team2')='string'))) AND (a ? 'score' AND (a->'score'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'score')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'score'))=a->'score' ELSE false END))) AND (a ? 'full_time' AND (a->'full_time'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'full_time')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'full_time'))=a->'full_time' ELSE false END))) AND (a ? 'half_time' AND (a->'half_time'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'half_time')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'half_time'))=a->'half_time' ELSE false END))) AND (a ? 'extra_time' AND (a->'extra_time'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'extra_time')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'extra_time'))=a->'extra_time' ELSE false END))) AND (a ? 'penalties' AND (a->'penalties'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'penalties')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'penalties'))=a->'penalties' ELSE false END))))
WHEN 'support_openliga' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['competition','season','source_license','source_name','source_url','source_data_url']::text[])='{}'::jsonb AND (a ? 'competition' AND (a->'competition'='null'::jsonb OR (jsonb_typeof(a->'competition')='string'))) AND (a ? 'season' AND (a->'season'='null'::jsonb OR (jsonb_typeof(a->'season')='string'))) AND (a ? 'source_license' AND (a->'source_license'='null'::jsonb OR (jsonb_typeof(a->'source_license')='string'))) AND (a ? 'source_name' AND (a->'source_name'='null'::jsonb OR (jsonb_typeof(a->'source_name')='string'))) AND (a ? 'source_url' AND (a->'source_url'='null'::jsonb OR (jsonb_typeof(a->'source_url')='string'))) AND (a ? 'source_data_url' AND (a->'source_data_url'='null'::jsonb OR (jsonb_typeof(a->'source_data_url')='string'))))
WHEN 'support_openliga_fixture' THEN (jsonb_typeof(a)='object' AND (a - ARRAY['fixture_date','fixture_key','home','away','home_id','away_id','status','group_number','round','round_name','score','penalties','notes']::text[])='{}'::jsonb AND (a ? 'fixture_date' AND (a->'fixture_date'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'fixture_date')='string' AND (a->>'fixture_date') ~ '^\d{4}-\d{2}-\d{2}$' THEN (a->>'fixture_date')::date IS NOT NULL ELSE false END))) AND (a ? 'fixture_key' AND (a->'fixture_key'='null'::jsonb OR (jsonb_typeof(a->'fixture_key')='string'))) AND (a ? 'home' AND (a->'home'='null'::jsonb OR (jsonb_typeof(a->'home')='string'))) AND (a ? 'away' AND (a->'away'='null'::jsonb OR (jsonb_typeof(a->'away')='string'))) AND (a ? 'home_id' AND (a->'home_id'='null'::jsonb OR (jsonb_typeof(a->'home_id')='string'))) AND (a ? 'away_id' AND (a->'away_id'='null'::jsonb OR (jsonb_typeof(a->'away_id')='string'))) AND (a ? 'status' AND (a->'status'='null'::jsonb OR (jsonb_typeof(a->'status')='string'))) AND (a ? 'group_number' AND (a->'group_number'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'group_number')='number' THEN (a->>'group_number')::integer IS NOT NULL ELSE false END))) AND (a ? 'round' AND (a->'round'='null'::jsonb OR (jsonb_typeof(a->'round')='string'))) AND (a ? 'round_name' AND (a->'round_name'='null'::jsonb OR (jsonb_typeof(a->'round_name')='string'))) AND (a ? 'score' AND (a->'score'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'score')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'score'))=a->'score' ELSE false END))) AND (a ? 'penalties' AND (a->'penalties'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'penalties')='array' THEN to_jsonb(statarena_app.record_integer_array(a->'penalties'))=a->'penalties' ELSE false END))) AND (a ? 'notes' AND (a->'notes'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'notes')='array' THEN to_jsonb(statarena_app.record_text_array(a->'notes'))=a->'notes' ELSE false END))))
ELSE false END,false); $$;

CREATE TABLE IF NOT EXISTS statarena_app.support_records (
 resource_id bigint NOT NULL REFERENCES statarena_app.support_projection(id) ON DELETE CASCADE,
 record_kind text NOT NULL, path integer[] NOT NULL,
 parent_kind text, parent_path integer[], position integer, metric_label text,
 missing text[] NOT NULL, null_groups text[] NOT NULL, negative_zero text[] NOT NULL DEFAULT '{}', attributes jsonb NOT NULL,
 PRIMARY KEY(resource_id,record_kind,path),
 FOREIGN KEY(resource_id,parent_kind,parent_path)
   REFERENCES statarena_app.support_records(resource_id,record_kind,path) ON DELETE CASCADE,
 UNIQUE NULLS NOT DISTINCT(resource_id,record_kind,parent_path,position),
 CHECK(coalesce(array_ndims(path)=1,true) AND array_position(path,NULL) IS NULL AND 0<=ALL(path)),
 CHECK(parent_path IS NULL OR (coalesce(array_ndims(parent_path)=1,true) AND array_position(parent_path,NULL) IS NULL AND 0<=ALL(parent_path))),
 CHECK(array_position(missing,NULL) IS NULL AND array_position(null_groups,NULL) IS NULL AND array_position(negative_zero,NULL) IS NULL),
 CHECK(octet_length(attributes::text)<=8388608),
 CHECK(statarena_app.support_attributes_valid(record_kind,attributes)),
 CHECK(coalesce(CASE record_kind
 WHEN 'support_standing' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_standing_table' THEN (parent_kind='support_standing' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_standing_row' THEN (parent_kind='support_standing_table' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=2 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_stadium' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_stadium_plan' THEN (parent_kind='support_stadium' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_club' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_coach' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_honours' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_honour' THEN (parent_kind='support_honours' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_honour_season' THEN (parent_kind='support_honour' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=2 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_honour_display_group' THEN (parent_kind='support_honours' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_honour_display_item' THEN (parent_kind='support_honour_display_group' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=2 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_nations' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_nations_fixture' THEN (parent_kind='support_nations' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_cup' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_cup_fixture' THEN (parent_kind='support_cup' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 WHEN 'support_openliga' THEN (path='{}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'support_openliga_fixture' THEN (parent_kind='support_openliga' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND parent_path=path[1:cardinality(path)-1] AND position=path[cardinality(path)] AND metric_label IS NULL)
 ELSE false END,false))
);

ALTER TABLE statarena_app.support_records ADD CONSTRAINT support_negative_zero_fields CHECK(coalesce(CASE record_kind
 WHEN 'support_standing' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_standing_table' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_standing_row' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_stadium' THEN negative_zero <@ ARRAY['coordinates_lat','coordinates_lon']::text[] AND (NOT 'coordinates_lat'=ANY(negative_zero) OR attributes->'coordinates_lat'='0'::jsonb) AND (NOT 'coordinates_lon'=ANY(negative_zero) OR attributes->'coordinates_lon'='0'::jsonb)
 WHEN 'support_stadium_plan' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_club' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_coach' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_honours' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_honour' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_honour_season' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_honour_display_group' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_honour_display_item' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_nations' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_nations_fixture' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_cup' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_cup_fixture' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_openliga' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'support_openliga_fixture' THEN negative_zero <@ ARRAY[]::text[]
 ELSE false END,false));

CREATE INDEX IF NOT EXISTS support_records_scan ON statarena_app.support_records(record_kind,resource_id,path);

CREATE INDEX IF NOT EXISTS support_records_parent ON statarena_app.support_records(resource_id,parent_kind,parent_path);

CREATE UNIQUE INDEX IF NOT EXISTS support_records_labels ON statarena_app.support_records(resource_id,record_kind,parent_path,metric_label) WHERE metric_label IS NOT NULL;

