(a->>'expected_goals_on_target')::double precision IS NOT NULL ELSE false END))) AND (a ? 'goal_crossed_y' AND (a->'goal_crossed_y'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'goal_crossed_y')='number' THEN (a->>'goal_crossed_y')::double precision IS NOT NULL ELSE false END))) AND (a ? 'goal_crossed_z' AND (a->'goal_crossed_z'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'goal_crossed_z')='number' THEN (a->>'goal_crossed_z')::double precision IS NOT NULL ELSE false END))) AND (a ? 'blocked_x' AND (a->'blocked_x'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'blocked_x')='number' THEN (a->>'blocked_x')::double precision IS NOT NULL ELSE false END))) AND (a ? 'blocked_y' AND (a->'blocked_y'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'blocked_y')='number' THEN (a->>'blocked_y')::double precision IS NOT NULL ELSE false END))) AND (a ? 'is_on_target' AND (a->'is_on_target'='null'::jsonb OR (jsonb_typeof(a->'is_on_target')='boolean'))) AND (a ? 'is_inside_box' AND (a->'is_inside_box'='null'::jsonb OR (jsonb_typeof(a->'is_inside_box')='boolean'))) AND (a ? 'is_blocked' AND (a->'is_blocked'='null'::jsonb OR (jsonb_typeof(a->'is_blocked')='boolean'))) AND (a ? 'player_id' AND (a->'player_id'='null'::jsonb OR (jsonb_typeof(a->'player_id')='string'))) AND (a ? 'player_name' AND (a->'player_name'='null'::jsonb OR (jsonb_typeof(a->'player_name')='string'))) AND (a ? 'player_image_url' AND (a->'player_image_url'='null'::jsonb OR (jsonb_typeof(a->'player_image_url')='string'))) AND (a ? 'player_position_id' AND (a->'player_position_id'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'player_position_id')='number' THEN (a->>'player_position_id')::integer IS NOT NULL ELSE false END))) AND (a ? 'player_shirt_number' AND (a->'player_shirt_number'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'player_shirt_number')='number' THEN (a->>'player_shirt_number')::integer IS NOT NULL ELSE false END))) AND (a ? 'keeper_id' AND (a->'keeper_id'='null'::jsonb OR (jsonb_typeof(a->'keeper_id')='string'))) AND (a ? 'keeper_name' AND (a->'keeper_name'='null'::jsonb OR (jsonb_typeof(a->'keeper_name')='string'))) AND (a ? 'keeper_image_url' AND (a->'keeper_image_url'='null'::jsonb OR (jsonb_typeof(a->'keeper_image_url')='string'))) AND (a ? 'keeper_position_id' AND (a->'keeper_position_id'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'keeper_position_id')='number' THEN (a->>'keeper_position_id')::integer IS NOT NULL ELSE false END))) AND (a ? 'keeper_shirt_number' AND (a->'keeper_shirt_number'='null'::jsonb OR (CASE WHEN jsonb_typeof(a->'keeper_shirt_number')='number' THEN (a->>'keeper_shirt_number')::integer IS NOT NULL ELSE false END))) AND (a ? 'is_own_goal' AND (a->'is_own_goal'='null'::jsonb OR (jsonb_typeof(a->'is_own_goal')='boolean'))) AND (a ? 'is_saved_off_line' AND (a->'is_saved_off_line'='null'::jsonb OR (jsonb_typeof(a->'is_saved_off_line')='boolean'))))
ELSE false END,false); $$;

CREATE TABLE IF NOT EXISTS statarena_app.detail_records (
 resource_id bigint NOT NULL REFERENCES statarena_app.match_families(resource_id) ON DELETE CASCADE,
 record_kind text NOT NULL, path integer[] NOT NULL,
 parent_kind text, parent_path integer[], position integer, metric_label text,
 missing text[] NOT NULL, null_groups text[] NOT NULL, negative_zero text[] NOT NULL DEFAULT '{}', attributes jsonb NOT NULL,
 PRIMARY KEY(resource_id,record_kind,path),
 FOREIGN KEY(resource_id,parent_kind,parent_path)
   REFERENCES statarena_app.detail_records(resource_id,record_kind,path) ON DELETE CASCADE,
 UNIQUE NULLS NOT DISTINCT(resource_id,record_kind,parent_path,position),
 CHECK(coalesce(array_ndims(path)=1,true) AND array_position(path,NULL) IS NULL AND 0<=ALL(path)),
 CHECK(parent_path IS NULL OR (coalesce(array_ndims(parent_path)=1,true) AND array_position(parent_path,NULL) IS NULL AND 0<=ALL(parent_path))),
 CHECK(array_position(missing,NULL) IS NULL AND array_position(null_groups,NULL) IS NULL AND array_position(negative_zero,NULL) IS NULL),
 CHECK(octet_length(attributes::text)<=8388608),
 CHECK(statarena_app.detail_attributes_valid(record_kind,attributes)),
 CHECK(coalesce(CASE record_kind
 WHEN 'match_summaries' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'event_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'match_events' THEN (parent_kind='event_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'shot_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'shot_periods' THEN (parent_kind='shot_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'match_shots' THEN (parent_kind='shot_periods' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'team_stat_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'team_stat_periods' THEN (parent_kind='team_stat_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'team_stat_groups' THEN (parent_kind='team_stat_periods' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'team_stat_items' THEN (parent_kind='team_stat_groups' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'lineup_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'lineup_home_starters' THEN (parent_kind='lineup_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'lineup_home_substitutes' THEN (parent_kind='lineup_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'lineup_away_starters' THEN (parent_kind='lineup_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'lineup_away_substitutes' THEN (parent_kind='lineup_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'momentum_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'momentum_points' THEN (parent_kind='momentum_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'h2h_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'h2h_matches' THEN (parent_kind='h2h_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'advanced_team_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'advanced_team_totals' THEN (parent_kind='advanced_team_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'advanced_player_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'advanced_player_totals' THEN (parent_kind='advanced_player_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'network_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'pass_networks' THEN (parent_kind='network_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'pass_nodes' THEN (parent_kind='pass_networks' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'pass_edges' THEN (parent_kind='pass_networks' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'heatmap_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'team_heatmaps' THEN (parent_kind='heatmap_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'player_heatmaps' THEN (parent_kind='heatmap_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 WHEN 'player_shot_sheets' THEN (path='{0}'::integer[] AND parent_kind IS NULL AND parent_path IS NULL AND position IS NULL AND metric_label IS NULL)
 WHEN 'individual_player_shots' THEN (parent_kind='player_shot_sheets' AND parent_path IS NOT NULL AND position>=0 AND cardinality(path)=1 AND cardinality(parent_path)=1 AND metric_label IS NULL)
 ELSE false END,false))
);

ALTER TABLE statarena_app.detail_records ADD CONSTRAINT detail_negative_zero_fields CHECK(coalesce(CASE record_kind
 WHEN 'match_summaries' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'event_sheets' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'match_events' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'shot_sheets' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'shot_periods' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'match_shots' THEN negative_zero <@ ARRAY['x','y','expected_goals','expected_goals_on_target','goal_crossed_y','goal_crossed_z','blocked_x','blocked_y']::text[] AND (NOT 'x'=ANY(negative_zero) OR attributes->'x'='0'::jsonb) AND (NOT 'y'=ANY(negative_zero) OR attributes->'y'='0'::jsonb) AND (NOT 'expected_goals'=ANY(negative_zero) OR attributes->'expected_goals'='0'::jsonb) AND (NOT 'expected_goals_on_target'=ANY(negative_zero) OR attributes->'expected_goals_on_target'='0'::jsonb) AND (NOT 'goal_crossed_y'=ANY(negative_zero) OR attributes->'goal_crossed_y'='0'::jsonb) AND (NOT 'goal_crossed_z'=ANY(negative_zero) OR attributes->'goal_crossed_z'='0'::jsonb) AND (NOT 'blocked_x'=ANY(negative_zero) OR attributes->'blocked_x'='0'::jsonb) AND (NOT 'blocked_y'=ANY(negative_zero) OR attributes->'blocked_y'='0'::jsonb)
 WHEN 'team_stat_sheets' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'team_stat_periods' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'team_stat_groups' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'team_stat_items' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'lineup_sheets' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'lineup_home_starters' THEN negative_zero <@ ARRAY['pitch_x','pitch_y']::text[] AND (NOT 'pitch_x'=ANY(negative_zero) OR attributes->'pitch_x'='0'::jsonb) AND (NOT 'pitch_y'=ANY(negative_zero) OR attributes->'pitch_y'='0'::jsonb)
 WHEN 'lineup_home_substitutes' THEN negative_zero <@ ARRAY['pitch_x','pitch_y']::text[] AND (NOT 'pitch_x'=ANY(negative_zero) OR attributes->'pitch_x'='0'::jsonb) AND (NOT 'pitch_y'=ANY(negative_zero) OR attributes->'pitch_y'='0'::jsonb)
 WHEN 'lineup_away_starters' THEN negative_zero <@ ARRAY['pitch_x','pitch_y']::text[] AND (NOT 'pitch_x'=ANY(negative_zero) OR attributes->'pitch_x'='0'::jsonb) AND (NOT 'pitch_y'=ANY(negative_zero) OR attributes->'pitch_y'='0'::jsonb)
 WHEN 'lineup_away_substitutes' THEN negative_zero <@ ARRAY['pitch_x','pitch_y']::text[] AND (NOT 'pitch_x'=ANY(negative_zero) OR attributes->'pitch_x'='0'::jsonb) AND (NOT 'pitch_y'=ANY(negative_zero) OR attributes->'pitch_y'='0'::jsonb)
 WHEN 'momentum_sheets' THEN negative_zero <@ ARRAY[]::text[]
 WHEN 'momentum_points' THEN negative_zero <@ ARRAY['minute','value']::text[] AND (NOT 'minute'=ANY(negative_zero) OR attributes->'minute'='0'::jsonb) AND (NOT 'value'=ANY(negative_zero) OR attributes->'value'='0'::jsonb)
