CREATE INDEX IF NOT EXISTS detail_records_scan ON statarena_app.detail_records(record_kind,resource_id,path);

CREATE INDEX IF NOT EXISTS detail_records_parent ON statarena_app.detail_records(resource_id,parent_kind,parent_path);

CREATE UNIQUE INDEX IF NOT EXISTS detail_records_labels ON statarena_app.detail_records(resource_id,record_kind,parent_path,metric_label) WHERE metric_label IS NOT NULL;

CREATE OR REPLACE VIEW statarena_next.cat_archive_goals AS SELECT
 r.resource_id AS "resource_id",
 r.path[1] AS "record_no",
 r.missing AS "missing",
 r.null_groups AS "null_groups",
 (r.attributes->>'season')::text AS "season",
 (r.attributes->>'source_coverage')::text AS "source_coverage",
 (r.attributes->>'source_license')::text AS "source_license",
 (r.attributes->>'source_licenseUrl')::text AS "source_licenseUrl",
 (r.attributes->>'source_name')::text AS "source_name",
 (r.attributes->>'source_revision')::text AS "source_revision",
 (r.attributes->>'source_url')::text AS "source_url"
FROM statarena_app.catalog_records r WHERE r.record_kind='cat_archive_goals';

CREATE OR REPLACE VIEW statarena_next.cat_archive_goals_competitions AS SELECT
 r.resource_id AS "resource_id",
 r.path[1] AS "record_no",
 r.missing AS "missing",
 r.null_groups AS "null_groups",
 r.parent_path[1] AS "parent_no",
 r.position AS "position",
 (r.attributes->>'calendarYear')::integer AS "calendarYear",
 (r.attributes->>'country')::text AS "country",
 (r.attributes->>'id')::text AS "id",
 (r.attributes->>'name')::text AS "name"
FROM statarena_app.catalog_records r WHERE r.record_kind='cat_archive_goals_competitions';

CREATE OR REPLACE VIEW statarena_next.cat_archive_goals_competitions_events AS SELECT
 r.resource_id AS "resource_id",
 r.path[1] AS "record_no",
 r.missing AS "missing",
 r.null_groups AS "null_groups",
 r.parent_path[1] AS "parent_no",
 r.position AS "position",
 (r.attributes->>'date')::text AS "date",
 (r.attributes->>'match')::text AS "match",
 (r.attributes->>'minute')::text AS "minute",
 (r.attributes->>'player')::text AS "player",
 statarena_app.record_integer_array(r.attributes->'score') AS "score",
 (r.attributes->>'scoreDisagreement')::boolean AS "scoreDisagreement",
 (r.attributes->>'sourceSeason')::text AS "sourceSeason",
 (r.attributes->>'team')::text AS "team"
FROM statarena_app.catalog_records r WHERE r.record_kind='cat_archive_goals_competitions_events';

CREATE OR REPLACE VIEW statarena_next.cat_archive_goals_index AS SELECT
 r.resource_id AS "resource_id",
 r.path[1] AS "record_no",
 r.missing AS "missing",
 r.null_groups AS "null_groups",
 (r.attributes->>'duplicatesRemoved')::integer AS "duplicatesRemoved",
 (r.attributes->>'schemaVersion')::integer AS "schemaVersion",
 (r.attributes->>'source_coverage')::text AS "source_coverage",
 (r.attributes->>'source_license')::text AS "source_license",
 (r.attributes->>'source_licenseUrl')::text AS "source_licenseUrl",
 (r.attributes->>'source_name')::text AS "source_name",
 (r.attributes->>'source_revision')::text AS "source_revision",
 (r.attributes->>'source_url')::text AS "source_url",
 (r.attributes->>'unassignedEvents')::integer AS "unassignedEvents"
FROM statarena_app.catalog_records r WHERE r.record_kind='cat_archive_goals_index';

CREATE OR REPLACE VIEW statarena_next.cat_archive_goals_index_seasons AS SELECT
 r.resource_id AS "resource_id",
 r.path[1] AS "record_no",
