 CASE WHEN 'x'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'x')::double precision END AS "x",
 CASE WHEN 'y'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'y')::double precision END AS "y",
 CASE WHEN 'expected_goals'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'expected_goals')::double precision END AS "expected_goals",
 CASE WHEN 'expected_goals_on_target'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'expected_goals_on_target')::double precision END AS "expected_goals_on_target",
 CASE WHEN 'goal_crossed_y'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'goal_crossed_y')::double precision END AS "goal_crossed_y",
 CASE WHEN 'goal_crossed_z'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'goal_crossed_z')::double precision END AS "goal_crossed_z",
