 (r.attributes->>'keeper_position_id')::integer AS "keeper_position_id",
 (r.attributes->>'keeper_shirt_number')::integer AS "keeper_shirt_number",
 (r.attributes->>'is_own_goal')::boolean AS "is_own_goal",
