 CASE WHEN 'blocked_y'=ANY(r.negative_zero) THEN '-0'::double precision ELSE (r.attributes->>'blocked_y')::double precision END AS "blocked_y",
 (r.attributes->>'is_on_target')::boolean AS "is_on_target",
