 (r.attributes->>'is_blocked')::boolean AS "is_blocked",
 (r.attributes->>'player_id')::text AS "player_id",
 (r.attributes->>'player_name')::text AS "player_name",
 (r.attributes->>'player_image_url')::text AS "player_image_url",
 (r.attributes->>'player_position_id')::integer AS "player_position_id",
 (r.attributes->>'player_shirt_number')::integer AS "player_shirt_number",
 (r.attributes->>'keeper_id')::text AS "keeper_id",
 (r.attributes->>'keeper_name')::text AS "keeper_name",
 (r.attributes->>'keeper_image_url')::text AS "keeper_image_url",
