CREATE OR REPLACE FUNCTION statarena_next.read_cat_archive_goals(r statarena_next.cat_archive_goals) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT (jsonb_build_object('competitions', CASE WHEN 'competitions'=ANY(r.null_groups) THEN NULL ELSE (SELECT coalesce(jsonb_agg((jsonb_build_object('calendarYear', r1."calendarYear",
'country', r1."country",
'events', CASE WHEN 'events'=ANY(r1.null_groups) THEN NULL ELSE (SELECT coalesce(jsonb_agg((jsonb_build_object('date', r2."date",
'match', r2."match",
'minute', r2."minute",
'player', r2."player",
'score', r2."score",
'scoreDisagreement', r2."scoreDisagreement",
'sourceSeason', r2."sourceSeason",
'team', r2."team") - r2.missing) ORDER BY r2.position), '[]'::jsonb) FROM statarena_next.cat_archive_goals_competitions_events r2
 WHERE r2.resource_id=r1.resource_id AND r2.parent_no=r1.record_no) END,
'id', r1."id",
'name', r1."name") - r1.missing) ORDER BY r1.position), '[]'::jsonb) FROM statarena_next.cat_archive_goals_competitions r1
 WHERE r1.resource_id=r.resource_id AND r1.parent_no=r.record_no) END,
'season', r."season",
'source', CASE WHEN 'source'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('coverage', r."source_coverage",
'license', r."source_license",
'licenseUrl', r."source_licenseUrl",
'name', r."source_name",
'revision', r."source_revision",
'url', r."source_url") - array_remove(ARRAY[CASE WHEN 'source.coverage'=ANY(r.missing) THEN 'coverage' END, CASE WHEN 'source.license'=ANY(r.missing) THEN 'license' END, CASE WHEN 'source.licenseUrl'=ANY(r.missing) THEN 'licenseUrl' END, CASE WHEN 'source.name'=ANY(r.missing) THEN 'name' END, CASE WHEN 'source.revision'=ANY(r.missing) THEN 'revision' END, CASE WHEN 'source.url'=ANY(r.missing) THEN 'url' END],NULL)) END) - r.missing); $$;

