CREATE OR REPLACE FUNCTION statarena_next.catalog_response(c statarena_app.catalog_editions) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT CASE c.model
WHEN 'archive_goals' THEN (SELECT statarena_next.read_cat_archive_goals(r) FROM statarena_next.cat_archive_goals r WHERE r.resource_id=c.resource_id)
WHEN 'archive_goals_index' THEN (SELECT statarena_next.read_cat_archive_goals_index(r) FROM statarena_next.cat_archive_goals_index r WHERE r.resource_id=c.resource_id)
WHEN 'archive_results' THEN (SELECT statarena_next.read_cat_archive_results(r) FROM statarena_next.cat_archive_results r WHERE r.resource_id=c.resource_id)
WHEN 'archive_results_index' THEN (SELECT statarena_next.read_cat_archive_results_index(r) FROM statarena_next.cat_archive_results_index r WHERE r.resource_id=c.resource_id)
WHEN 'club_links' THEN (SELECT statarena_next.read_cat_club_links(r) FROM statarena_next.cat_club_links r WHERE r.resource_id=c.resource_id)
WHEN 'cup_nations_results' THEN (SELECT statarena_next.read_cat_cup_nations_results(r) FROM statarena_next.cat_cup_nations_results r WHERE r.resource_id=c.resource_id)
WHEN 'cup_native' THEN (SELECT statarena_next.read_cat_cup_native(r) FROM statarena_next.cat_cup_native r WHERE r.resource_id=c.resource_id)
WHEN 'cup_open_cups' THEN (SELECT statarena_next.read_cat_cup_open_cups(r) FROM statarena_next.cat_cup_open_cups r WHERE r.resource_id=c.resource_id)
WHEN 'cup_openligadb' THEN (SELECT statarena_next.read_cat_cup_openligadb(r) FROM statarena_next.cat_cup_openligadb r WHERE r.resource_id=c.resource_id)
WHEN 'cup_standings' THEN (SELECT statarena_next.read_cat_cup_standings(r) FROM statarena_next.cat_cup_standings r WHERE r.resource_id=c.resource_id)
WHEN 'cup_worker_index' THEN (SELECT statarena_next.read_cat_cup_worker_index(r) FROM statarena_next.cat_cup_worker_index r WHERE r.resource_id=c.resource_id)
WHEN 'matchdays' THEN (SELECT statarena_next.read_cat_matchdays(r) FROM statarena_next.cat_matchdays r WHERE r.resource_id=c.resource_id)
WHEN 'profile_catalog' THEN (SELECT statarena_next.read_cat_profile_catalog(r) FROM statarena_next.cat_profile_catalog r WHERE r.resource_id=c.resource_id)
WHEN 'profile_leagues' THEN (SELECT statarena_next.read_cat_profile_leagues(r) FROM statarena_next.cat_profile_leagues r WHERE r.resource_id=c.resource_id)
WHEN 'profile_players' THEN (SELECT statarena_next.read_cat_profile_players(r) FROM statarena_next.cat_profile_players r WHERE r.resource_id=c.resource_id)
WHEN 'profile_teams' THEN (SELECT statarena_next.read_cat_profile_teams(r) FROM statarena_next.cat_profile_teams r WHERE r.resource_id=c.resource_id)
WHEN 'ranking_fifa_men' THEN (SELECT statarena_next.read_cat_ranking_fifa_men(r) FROM statarena_next.cat_ranking_fifa_men r WHERE r.resource_id=c.resource_id)
WHEN 'ranking_index' THEN (SELECT statarena_next.read_cat_ranking_index(r) FROM statarena_next.cat_ranking_index r WHERE r.resource_id=c.resource_id)
WHEN 'ranking_sportsapi' THEN (SELECT statarena_next.read_cat_ranking_sportsapi(r) FROM statarena_next.cat_ranking_sportsapi r WHERE r.resource_id=c.resource_id)
WHEN 'ranking_uefa_associations' THEN (SELECT statarena_next.read_cat_ranking_uefa_associations(r) FROM statarena_next.cat_ranking_uefa_associations r WHERE r.resource_id=c.resource_id)
WHEN 'ranking_uefa_clubs' THEN (SELECT statarena_next.read_cat_ranking_uefa_clubs(r) FROM statarena_next.cat_ranking_uefa_clubs r WHERE r.resource_id=c.resource_id)
WHEN 'supp_fixtures' THEN (SELECT statarena_next.read_cat_supp_fixtures(r) FROM statarena_next.cat_supp_fixtures r WHERE r.resource_id=c.resource_id)
WHEN 'supp_goals' THEN (SELECT statarena_next.read_cat_supp_goals(r) FROM statarena_next.cat_supp_goals r WHERE r.resource_id=c.resource_id)
WHEN 'supp_index' THEN (SELECT statarena_next.read_cat_supp_index(r) FROM statarena_next.cat_supp_index r WHERE r.resource_id=c.resource_id)
WHEN 'supp_results' THEN (SELECT statarena_next.read_cat_supp_results(r) FROM statarena_next.cat_supp_results r WHERE r.resource_id=c.resource_id)
END; $$;

